effect.shader:
// Rec.709 — os mesmos pesos de `luma-key.xml`.
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

void main() {
    vec4 cor = texture(inputImg, acScreenNorm);
    float luz = dot(cor.rgb, LUMA);

    // A rampa nunca é zero: suavidade 0 viraria um degrau de um tom só, e
    // degrau em máscara é serrilhado na borda.
    float rampaPreto = max(blackSoftness, 0.004);
    float rampaBranco = max(whiteSoftness, 0.004);

    // Sobe de 0 pra 1 cruzando o ponto de preto, desce de 1 pra 0 cruzando o
    // ponto de branco — o produto dos dois é 1 só DENTRO da faixa.
    float acimaDoPreto = smoothstep(blackPoint - rampaPreto, blackPoint + rampaPreto, luz);
    float abaixoDoBranco = 1.0 - smoothstep(whitePoint - rampaBranco, whitePoint + rampaBranco, luz);
    float alfa = clamp(acimaDoPreto * abaixoDoBranco, 0.0, 1.0);

    if (invert) alfa = 1.0 - alfa;

    if (showMask) {
        fragColor = vec4(vec3(alfa), 1.0);
        return;
    }

    fragColor = vec4(cor.rgb, cor.a * alfa);
}
